     1→package lexer
     2→
     3→import (
     4→	"fmt"
     5→	"strings"
     6→	"unicode"
     7→)
     8→
     9→const (
    10→	maxInputSize      = 10_000_000
    11→	maxIdentifierLen  = 10_000
    12→	maxStringLen      = 1_000_000
    13→	maxNumberLen      = 100
    14→)
    15→
    16→// Lexer tokenizes V-compatible source code
    17→type Lexer struct {
    18→	input     string
    19→	pos       int
    20→	line      int
    21→	column    int
    22→	keywords  map[string]TokenType
    23→}
    24→
    25→// New creates a new lexer with input validation
    26→func New(input string) (*Lexer, error) {
    27→	// 보안: 입력 크기 제한
    28→	if len(input) > maxInputSize {
    29→		return nil, fmt.Errorf("input too large: %d bytes (max %d)", len(input), maxInputSize)
    30→	}
    31→
    32→	// 보안: NULL 바이트 확인 (단일 바이트로 검사)
    33→	for _, r := range input {
    34→		if r == 0 {
    35→			return nil, fmt.Errorf("input contains null bytes")
    36→		}
    37→	}
    38→
    39→	keywords := map[string]TokenType{
    40→		"fn":        TknFn,
    41→		"let":       TknLet,
    42→		"mut":       TknMut,
    43→		"const":     TknConst,
    44→		"if":        TknIf,
    45→		"else":      TknElse,
    46→		"for":       TknFor,
    47→		"in":        TknIn,
    48→		"match":     TknMatch,
    49→		"type":      TknType,
    50→		"struct":    TknStruct,
    51→		"interface": TknInterface,
    52→		"enum":      TknEnum,
    53→		"trait":     TknTrait,
    54→		"impl":      TknImpl,
    55→		"return":    TknReturn,
    56→		"module":    TknModule,
    57→		"import":    TknImport,
    58→		"true":      TknTrue,
    59→		"false":     TknFalse,
    60→		"none":      TknNone,
    61→	}
    62→
    63→	return &Lexer{
    64→		input:    input,
    65→		pos:      0,
    66→		line:     1,
    67→		column:   1,
    68→		keywords: keywords,
    69→	}, nil
    70→}
    71→
    72→// Tokenize returns all tokens from the input
    73→func (l *Lexer) Tokenize() ([]Token, error) {
    74→	var tokens []Token
    75→
    76→	for {
    77→		l.skipWhitespaceAndComments()
    78→
    79→		if l.isAtEnd() {
    80→			tokens = append(tokens, Token{
    81→				Type:   TknEof,
    82→				Text:   "",
    83→				Line:   l.line,
    84→				Column: l.column,
    85→			})
    86→			break
    87→		}
    88→
    89→		token, err := l.nextToken()
    90→		if err != nil {
    91→			return nil, err
    92→		}
    93→		tokens = append(tokens, token)
    94→	}
    95→
    96→	return tokens, nil
    97→}
    98→
    99→func (l *Lexer) nextToken() (Token, error) {
   100→	startLine := l.line
   101→	startColumn := l.column
   102→	startPos := l.pos
   103→
   104→	ch := l.current()
   105→	var token Token
   106→
   107→	switch ch {
   108→	case '(':
   109→		l.advance()
   110→		token = Token{TknLParen, "(", startLine, startColumn}
   111→	case ')':
   112→		l.advance()
   113→		token = Token{TknRParen, ")", startLine, startColumn}
   114→	case '{':
   115→		l.advance()
   116→		token = Token{TknLBrace, "{", startLine, startColumn}
   117→	case '}':
   118→		l.advance()
   119→		token = Token{TknRBrace, "}", startLine, startColumn}
   120→	case '[':
   121→		l.advance()
   122→		token = Token{TknLBracket, "[", startLine, startColumn}
   123→	case ']':
   124→		l.advance()
   125→		token = Token{TknRBracket, "]", startLine, startColumn}
   126→	case ',':
   127→		l.advance()
   128→		token = Token{TknComma, ",", startLine, startColumn}
   129→	case ';':
   130→		l.advance()
   131→		token = Token{TknSemicolon, ";", startLine, startColumn}
   132→	case '@':
   133→		l.advance()
   134→		token = Token{TknAt, "@", startLine, startColumn}
   135→	case '~':
   136→		l.advance()
   137→		token = Token{TknTilde, "~", startLine, startColumn}
   138→	case '+':
   139→		l.advance()
   140→		if l.current() == '=' {
   141→			l.advance()
   142→			token = Token{TknPlusAssign, "+=", startLine, startColumn}
   143→		} else {
   144→			token = Token{TknPlus, "+", startLine, startColumn}
   145→		}
   146→	case '-':
   147→		l.advance()
   148→		switch l.current() {
   149→		case '=':
   150→			l.advance()
   151→			token = Token{TknMinusAssign, "-=", startLine, startColumn}
   152→		case '>':
   153→			l.advance()
   154→			token = Token{TknArrow, "->", startLine, startColumn}
   155→		default:
   156→			token = Token{TknMinus, "-", startLine, startColumn}
   157→		}
   158→	case '*':
   159→		l.advance()
   160→		if l.current() == '=' {
   161→			l.advance()
   162→			token = Token{TknStarAssign, "*=", startLine, startColumn}
   163→		} else {
   164→			token = Token{TknStar, "*", startLine, startColumn}
   165→		}
   166→	case '/':
   167→		l.advance()
   168→		if l.current() == '=' {
   169→			l.advance()
   170→			token = Token{TknSlashAssign, "/=", startLine, startColumn}
   171→		} else {
   172→			token = Token{TknSlash, "/", startLine, startColumn}
   173→		}
   174→	case '%':
   175→		l.advance()
   176→		token = Token{TknPercent, "%", startLine, startColumn}
   177→	case '^':
   178→		l.advance()
   179→		token = Token{TknCaret, "^", startLine, startColumn}
   180→	case '&':
   181→		l.advance()
   182→		if l.current() == '&' {
   183→			l.advance()
   184→			token = Token{TknLogicalAnd, "&&", startLine, startColumn}
   185→		} else {
   186→			token = Token{TknAmpersand, "&", startLine, startColumn}
   187→		}
   188→	case '|':
   189→		l.advance()
   190→		if l.current() == '|' {
   191→			l.advance()
   192→			token = Token{TknLogicalOr, "||", startLine, startColumn}
   193→		} else {
   194→			token = Token{TknPipe, "|", startLine, startColumn}
   195→		}
   196→	case '!':
   197→		l.advance()
   198→		if l.current() == '=' {
   199→			l.advance()
   200→			token = Token{TknNe, "!=", startLine, startColumn}
   201→		} else {
   202→			token = Token{TknNot, "!", startLine, startColumn}
   203→		}
   204→	case '?':
   205→		l.advance()
   206→		token = Token{TknQuestion, "?", startLine, startColumn}
   207→	case '=':
   208→		l.advance()
   209→		switch l.current() {
   210→		case '=':
   211→			l.advance()
   212→			token = Token{TknEq, "==", startLine, startColumn}
   213→		case '>':
   214→			l.advance()
   215→			token = Token{TknFatArrow, "=>", startLine, startColumn}
   216→		default:
   217→			token = Token{TknAssign, "=", startLine, startColumn}
   218→		}
   219→	case '<':
   220→		l.advance()
   221→		switch l.current() {
   222→		case '=':
   223→			l.advance()
   224→			token = Token{TknLe, "<=", startLine, startColumn}
   225→		case '<':
   226→			l.advance()
   227→			token = Token{TknLeftShift, "<<", startLine, startColumn}
   228→		default:
   229→			token = Token{TknLt, "<", startLine, startColumn}
   230→		}
   231→	case '>':
   232→		l.advance()
   233→		switch l.current() {
   234→		case '=':
   235→			l.advance()
   236→			token = Token{TknGe, ">=", startLine, startColumn}
   237→		case '>':
   238→			l.advance()
   239→			token = Token{TknRightShift, ">>", startLine, startColumn}
   240→		default:
   241→			token = Token{TknGt, ">", startLine, startColumn}
   242→		}
   243→	case ':':
   244→		l.advance()
   245→		switch l.current() {
   246→		case ':':
   247→			l.advance()
   248→			token = Token{TknDoubleColon, "::", startLine, startColumn}
   249→		case '=':
   250→			l.advance()
   251→			token = Token{TknColonAssign, ":=", startLine, startColumn}
   252→		default:
   253→			token = Token{TknColon, ":", startLine, startColumn}
   254→		}
   255→	case '.':
   256→		l.advance()
   257→		switch l.current() {
   258→		case '.':
   259→			l.advance()
   260→			if l.current() == '=' {
   261→				l.advance()
   262→				token = Token{TknDotDotEq, "..=", startLine, startColumn}
   263→			} else {
   264→				token = Token{TknDoubleDot, "..", startLine, startColumn}
   265→			}
   266→		default:
   267→			token = Token{TknDot, ".", startLine, startColumn}
   268→		}
   269→	case '"':
   270→		l.advance()
   271→		text, err := l.readString(byte('"'))
   272→		if err != nil {
   273→			return Token{}, err
   274→		}
   275→		token = Token{TknString, text, startLine, startColumn}
   276→	case '\'':
   277→		l.advance()
   278→		text, err := l.readString(byte('\''))
   279→		if err != nil {
   280→			return Token{}, err
   281→		}
   282→		token = Token{TknString, text, startLine, startColumn}
   283→	case '`':
   284→		l.advance()
   285→		text, err := l.readRawString()
   286→		if err != nil {
   287→			return Token{}, err
   288→		}
   289→		token = Token{TknRawString, text, startLine, startColumn}
   290→	default:
   291→		if unicode.IsDigit(rune(ch)) {
   292→			return l.readNumber(startLine, startColumn)
   293→		} else if unicode.IsLetter(rune(ch)) || ch == '_' {
   294→			return l.readIdentifier(startLine, startColumn)
   295→		} else {
   296→			return Token{}, fmt.Errorf("unexpected character at %d:%d: '%c'", l.line, l.column, ch)
   297→		}
   298→	}
   299→
   300→	token.Line = startLine
   301→	token.Column = startColumn
   302→	if token.Text == "" {
   303→		token.Text = string(l.input[startPos:l.pos])
   304→	}
   305→
   306→	return token, nil
   307→}
   308→
   309→func (l *Lexer) readIdentifier(line, column int) (Token, error) {
   310→	start := l.pos
   311→
   312→	for !l.isAtEnd() && (unicode.IsLetter(rune(l.current())) || unicode.IsDigit(rune(l.current())) || l.current() == '_') {
   313→		l.advance()
   314→	}
   315→
   316→	ident := l.input[start:l.pos]
   317→
   318→	// Check if it's a keyword
   319→	if tknType, ok := l.keywords[ident]; ok {
   320→		return Token{tknType, ident, line, column}, nil
   321→	}
   322→
   323→	return Token{TknIdentifier, ident, line, column}, nil
   324→}
   325→
   326→func (l *Lexer) readNumber(line, column int) (Token, error) {
   327→	start := l.pos
   328→
   329→	// 정수 부분
   330→	for !l.isAtEnd() && unicode.IsDigit(rune(l.current())) {
   331→		l.advance()
   332→	}
   333→
   334→	// 부동소수점 확인
   335→	if l.current() == '.' && l.isDigitAt(l.pos+1) {
   336→		l.advance() // skip '.'
   337→
   338→		for !l.isAtEnd() && unicode.IsDigit(rune(l.current())) {
   339→			l.advance()
   340→		}
   341→
   342→		return Token{TknFloat, l.input[start:l.pos], line, column}, nil
   343→	}
   344→
   345→	return Token{TknInteger, l.input[start:l.pos], line, column}, nil
   346→}
   347→
   348→func (l *Lexer) readString(quote byte) (string, error) {
   349→	start := l.pos
   350→
   351→	for !l.isAtEnd() && l.current() != quote {
   352→		if l.current() == '\\' {
   353→			l.advance()
   354→			if !l.isAtEnd() {
   355→				l.advance()
   356→			}
   357→		} else {
   358→			if l.current() == '\n' {
   359→				l.line++
   360→				l.column = 0
   361→			}
   362→			l.advance()
   363→		}
   364→	}
   365→
   366→	if l.isAtEnd() {
   367→		return "", fmt.Errorf("unterminated string at line %d", l.line)
   368→	}
   369→
   370→	content := l.input[start:l.pos]
   371→	l.advance() // skip closing quote
   372→
   373→	return l.unescapeString(content), nil
   374→}
   375→
   376→func (l *Lexer) readRawString() (string, error) {
   377→	start := l.pos
   378→
   379→	for !l.isAtEnd() && l.current() != '`' {
   380→		if l.current() == '\n' {
   381→			l.line++
   382→			l.column = 0
   383→		}
   384→		l.advance()
   385→	}
   386→
   387→	if l.isAtEnd() {
   388→		return "", fmt.Errorf("unterminated raw string at line %d", l.line)
   389→	}
   390→
   391→	content := l.input[start:l.pos]
   392→	l.advance() // skip closing backtick
   393→
   394→	return content, nil
   395→}
   396→
   397→func (l *Lexer) unescapeString(s string) string {
   398→	var result strings.Builder
   399→	i := 0
   400→	for i < len(s) {
   401→		if s[i] == '\\' && i+1 < len(s) {
   402→			switch s[i+1] {
   403→			case 'n':
   404→				result.WriteByte('\n')
   405→				i += 2
   406→			case 't':
   407→				result.WriteByte('\t')
   408→				i += 2
   409→			case 'r':
   410→				result.WriteByte('\r')
   411→				i += 2
   412→			case '\\':
   413→				result.WriteByte('\\')
   414→				i += 2
   415→			case '"':
   416→				result.WriteByte('"')
   417→				i += 2
   418→			case '\'':
   419→				result.WriteByte('\'')
   420→				i += 2
   421→			default:
   422→				result.WriteByte(s[i+1])
   423→				i += 2
   424→			}
   425→		} else {
   426→			result.WriteByte(s[i])
   427→			i++
   428→		}
   429→	}
   430→	return result.String()
   431→}
   432→
   433→func (l *Lexer) skipWhitespaceAndComments() {
   434→	for !l.isAtEnd() {
   435→		switch l.current() {
   436→		case ' ', '\t', '\r':
   437→			l.advance()
   438→		case '\n':
   439→			l.line++
   440→			l.column = 0
   441→			l.advance()
   442→		case '/' :
   443→			if l.peekNext() == '/' {
   444→				// 한 줄 주석
   445→				for !l.isAtEnd() && l.current() != '\n' {
   446→					l.advance()
   447→				}
   448→			} else if l.peekNext() == '*' {
   449→				// 블록 주석
   450→				l.advance()
   451→				l.advance()
   452→				for !l.isAtEnd() {
   453→					if l.current() == '*' && l.peekNext() == '/' {
   454→						l.advance()
   455→						l.advance()
   456→						break
   457→					}
   458→					if l.current() == '\n' {
   459→						l.line++
   460→						l.column = 0
   461→					}
   462→					l.advance()
   463→				}
   464→			} else {
   465→				return
   466→			}
   467→		default:
   468→			return
   469→		}
   470→	}
   471→}
   472→
   473→func (l *Lexer) current() byte {
   474→	if l.isAtEnd() {
   475→		return 0
   476→	}
   477→	return l.input[l.pos]
   478→}
   479→
   480→func (l *Lexer) peekNext() byte {
   481→	if l.pos+1 >= len(l.input) {
   482→		return 0
   483→	}
   484→	return l.input[l.pos+1]
   485→}
   486→
   487→func (l *Lexer) isDigitAt(pos int) bool {
   488→	if pos >= len(l.input) {
   489→		return false
   490→	}
   491→	return unicode.IsDigit(rune(l.input[pos]))
   492→}
   493→
   494→func (l *Lexer) advance() {
   495→	if !l.isAtEnd() {
   496→		l.pos++
   497→		l.column++
   498→	}
   499→}
   500→
   501→func (l *Lexer) isAtEnd() bool {
   502→	return l.pos >= len(l.input)
   503→}
   504→

