     1→// Package ast defines the Abstract Syntax Tree for FV 2.0
     2→package ast
     3→
     4→// Program represents the root AST node
     5→type Program struct {
     6→	Definitions []Definition
     7→	MainBody    []Statement
     8→}
     9→
    10→// Definition represents top-level declarations
    11→type Definition interface {
    12→	definitionNode()
    13→}
    14→
    15→// FunctionDef represents a function definition
    16→type FunctionDef struct {
    17→	Name       string
    18→	Parameters []Parameter
    19→	ReturnType *Type
    20→	Body       []Statement
    21→}
    22→
    23→func (*FunctionDef) definitionNode() {}
    24→
    25→// TypeDef represents a type definition
    26→type TypeDef struct {
    27→	Name   string
    28→	Fields []Field
    29→}
    30→
    31→func (*TypeDef) definitionNode() {}
    32→
    33→// StructDef represents a struct definition
    34→type StructDef struct {
    35→	Name   string
    36→	Fields []Field
    37→}
    38→
    39→func (*StructDef) definitionNode() {}
    40→
    41→// InterfaceDef represents an interface definition
    42→type InterfaceDef struct {
    43→	Name    string
    44→	Methods []MethodSig
    45→}
    46→
    47→func (*InterfaceDef) definitionNode() {}
    48→
    49→// EnumDef represents an enum definition
    50→type EnumDef struct {
    51→	Name     string
    52→	Variants []EnumVariant
    53→}
    54→
    55→func (*EnumDef) definitionNode() {}
    56→
    57→// Parameter represents a function parameter
    58→type Parameter struct {
    59→	Name string
    60→	Type *Type
    61→}
    62→
    63→// Field represents a struct/type field
    64→type Field struct {
    65→	Name      string
    66→	Type      *Type
    67→	Mutable   bool
    68→	Default   Expression
    69→}
    70→
    71→// MethodSig represents a method signature
    72→type MethodSig struct {
    73→	Name       string
    74→	Parameters []Parameter
    75→	ReturnType *Type
    76→}
    77→
    78→// EnumVariant represents an enum variant
    79→type EnumVariant struct {
    80→	Name  string
    81→	Types []Type
    82→}
    83→
    84→// Statement represents a statement
    85→type Statement interface {
    86→	statementNode()
    87→}
    88→
    89→// LetStatement represents a let binding
    90→type LetStatement struct {
    91→	Name    string
    92→	Type    *Type
    93→	Init    Expression
    94→	Mutable bool
    95→}
    96→
    97→func (*LetStatement) statementNode() {}
    98→
    99→// ConstStatement represents a const binding
   100→type ConstStatement struct {
   101→	Name  string
   102→	Type  *Type
   103→	Value Expression
   104→}
   105→
   106→func (*ConstStatement) statementNode() {}
   107→
   108→// IfStatement represents an if/else statement
   109→type IfStatement struct {
   110→	Condition Expression
   111→	ThenBody  []Statement
   112→	ElseBody  []Statement
   113→}
   114→
   115→func (*IfStatement) statementNode() {}
   116→
   117→// ForStatement represents a for loop
   118→type ForStatement struct {
   119→	Variable string
   120→	Iterator Expression
   121→	Body     []Statement
   122→}
   123→
   124→func (*ForStatement) statementNode() {}
   125→
   126→// ForRangeStatement represents a for range loop
   127→type ForRangeStatement struct {
   128→	Variable string
   129→	Start    Expression
   130→	End      Expression
   131→	Body     []Statement
   132→}
   133→
   134→func (*ForRangeStatement) statementNode() {}
   135→
   136→// MatchStatement represents a match expression
   137→type MatchStatement struct {
   138→	Expression Expression
   139→	Arms       []MatchArm
   140→}
   141→
   142→func (*MatchStatement) statementNode() {}
   143→
   144→// MatchArm represents a match arm
   145→type MatchArm struct {
   146→	Pattern Pattern
   147→	Body    []Statement
   148→}
   149→
   150→// Pattern represents a match pattern
   151→type Pattern interface {
   152→	patternNode()
   153→}
   154→
   155→// LiteralPattern matches a literal
   156→type LiteralPattern struct {
   157→	Value Expression
   158→}
   159→
   160→func (*LiteralPattern) patternNode() {}
   161→
   162→// IdentifierPattern matches an identifier
   163→type IdentifierPattern struct {
   164→	Name string
   165→}
   166→
   167→func (*IdentifierPattern) patternNode() {}
   168→
   169→// WildcardPattern matches anything
   170→type WildcardPattern struct{}
   171→
   172→func (*WildcardPattern) patternNode() {}
