     1→// Package typechecker implements type checking and inference for FV 2.0
     2→package typechecker
     3→
     4→import "fmt"
     5→
     6→// Type represents a type in FV 2.0
     7→type Type interface {
     8→	TypeString() string
     9→	Equal(other Type) bool
    10→}
    11→
    12→// PrimitiveType represents built-in types
    13→type PrimitiveType struct {
    14→	Name string // i64, f64, string, bool, none
    15→}
    16→
    17→func (p *PrimitiveType) TypeString() string { return p.Name }
    18→func (p *PrimitiveType) Equal(other Type) bool {
    19→	if o, ok := other.(*PrimitiveType); ok {
    20→		return p.Name == o.Name
    21→	}
    22→	return false
    23→}
    24→
    25→// ArrayType represents an array type
    26→type ArrayType struct {
    27→	ElementType Type
    28→}
    29→
    30→func (a *ArrayType) TypeString() string {
    31→	return "[" + a.ElementType.TypeString() + "]"
    32→}
    33→func (a *ArrayType) Equal(other Type) bool {
    34→	if o, ok := other.(*ArrayType); ok {
    35→		return a.ElementType.Equal(o.ElementType)
    36→	}
    37→	return false
    38→}
    39→
    40→// FunctionType represents a function type
    41→type FunctionType struct {
    42→	ParamTypes []Type
    43→	ReturnType Type
    44→}
    45→
    46→func (f *FunctionType) TypeString() string {
    47→	params := ""
    48→	for i, p := range f.ParamTypes {
    49→		if i > 0 {
    50→			params += ", "
    51→		}
    52→		params += p.TypeString()
    53→	}
    54→	return fmt.Sprintf("fn(%s) %s", params, f.ReturnType.TypeString())
    55→}
    56→func (f *FunctionType) Equal(other Type) bool {
    57→	if o, ok := other.(*FunctionType); ok {
    58→		if len(f.ParamTypes) != len(o.ParamTypes) {
    59→			return false
    60→		}
    61→		for i, p := range f.ParamTypes {
    62→			if !p.Equal(o.ParamTypes[i]) {
    63→				return false
    64→			}
    65→		}
    66→		return f.ReturnType.Equal(o.ReturnType)
    67→	}
    68→	return false
    69→}
    70→
    71→// OptionType represents Option[T]
    72→type OptionType struct {
    73→	InnerType Type
    74→}
    75→
    76→func (o *OptionType) TypeString() string {
    77→	return "Option[" + o.InnerType.TypeString() + "]"
    78→}
    79→func (o *OptionType) Equal(other Type) bool {
    80→	if oo, ok := other.(*OptionType); ok {
    81→		return o.InnerType.Equal(oo.InnerType)
    82→	}
    83→	return false
    84→}
    85→
    86→// ResultType represents Result[T, E]
    87→type ResultType struct {
    88→	OkType    Type
    89→	ErrorType Type
    90→}
    91→
    92→func (r *ResultType) TypeString() string {
    93→	return fmt.Sprintf("Result[%s, %s]", r.OkType.TypeString(), r.ErrorType.TypeString())
    94→}
    95→func (r *ResultType) Equal(other Type) bool {
    96→	if ro, ok := other.(*ResultType); ok {
    97→		return r.OkType.Equal(ro.OkType) && r.ErrorType.Equal(ro.ErrorType)
    98→	}
    99→	return false
   100→}
   101→
   102→// StructType represents a struct type
   103→type StructType struct {
   104→	Name   string
   105→	Fields map[string]Type
   106→}
   107→
   108→func (s *StructType) TypeString() string {
   109→	return "struct " + s.Name
   110→}
   111→func (s *StructType) Equal(other Type) bool {
   112→	if o, ok := other.(*StructType); ok {
   113→		return s.Name == o.Name
   114→	}
   115→	return false
   116→}
   117→
   118→// UnionType represents a union type (e.g., int | string)
   119→type UnionType struct {
   120→	Types []Type
   121→}
   122→
   123→func (u *UnionType) TypeString() string {
   124→	result := ""
   125→	for i, t := range u.Types {
   126→		if i > 0 {
   127→			result += " | "
   128→		}
   129→		result += t.TypeString()
   130→	}
   131→	return result
   132→}
   133→func (u *UnionType) Equal(other Type) bool {
   134→	if o, ok := other.(*UnionType); ok {
   135→		if len(u.Types) != len(o.Types) {
   136→			return false
   137→		}
   138→		for i, t := range u.Types {
   139→			if !t.Equal(o.Types[i]) {
   140→				return false
   141→			}
   142→		}
   143→		return true
   144→	}
   145→	return false
   146→}
   147→
   148→// Symbol represents a variable or function binding
   149→type Symbol struct {
   150→	Name string
   151→	Type Type
   152→	Kind string // "var", "function", "const", "type"
   153→}
   154→
   155→// Scope represents a scope level
   156→type Scope struct {
   157→	Symbols map[string]*Symbol
   158→	Parent  *Scope
   159→}
   160→
   161→// NewScope creates a new scope
   162→func NewScope(parent *Scope) *Scope {
   163→	return &Scope{
   164→		Symbols: make(map[string]*Symbol),
   165→		Parent:  parent,
   166→	}
   167→}
   168→
   169→// Define adds a symbol to the scope
   170→func (s *Scope) Define(name string, typ Type, kind string) {
   171→	s.Symbols[name] = &Symbol{
   172→		Name: name,
   173→		Type: typ,
   174→		Kind: kind,
   175→	}
   176→}
   177→
   178→// Lookup finds a symbol in this scope or parent scopes
   179→func (s *Scope) Lookup(name string) *Symbol {
   180→	if sym, ok := s.Symbols[name]; ok {
   181→		return sym
   182→	}
   183→	if s.Parent != nil {
   184→		return s.Parent.Lookup(name)
   185→	}
   186→	return nil
   187→}
   188→
   189→// Error represents a type checking error
   190→type Error struct {
   191→	Line    int
   192→	Column  int
   193→	Message string
   194→}
   195→
   196→func (e Error) String() string {
   197→	return fmt.Sprintf("%d:%d: %s", e.Line, e.Column, e.Message)
   198→}
