     1→// Package parser implements V-compatible syntax parsing
     2→package parser
     3→
     4→import (
     5→	"fmt"
     6→	"strconv"
     7→
     8→	"fv2-lang/internal/ast"
     9→	"fv2-lang/internal/lexer"
    10→)
    11→
    12→// Parser converts tokens to AST
    13→type Parser struct {
    14→	tokens   []lexer.Token
    15→	pos      int
    16→	errors   []string
    17→}
    18→
    19→// New creates a new parser
    20→func New(tokens []lexer.Token) *Parser {
    21→	return &Parser{
    22→		tokens: tokens,
    23→		pos:    0,
    24→		errors: []string{},
    25→	}
    26→}
    27→
    28→// Parse parses tokens into an AST (with error recovery)
    29→func (p *Parser) Parse() (*ast.Program, error) {
    30→	var definitions []ast.Definition
    31→	var mainBody []ast.Statement
    32→
    33→	for !p.isAtEnd() {
    34→		if p.match(lexer.TknEof) {
    35→			break
    36→		}
    37→
    38→		if p.check(lexer.TknFn) {
    39→			def, err := p.parseFunctionDef()
    40→			if err != nil {
    41→				p.errors = append(p.errors, err.Error())
    42→				p.synchronize() // Error recovery: skip to next definition
    43→				continue
    44→			}
    45→			if def != nil {
    46→				definitions = append(definitions, def)
    47→			}
    48→		} else if p.check(lexer.TknType) {
    49→			def, err := p.parseTypeDef()
    50→			if err != nil {
    51→				p.errors = append(p.errors, err.Error())
    52→				p.synchronize() // Error recovery
    53→				continue
    54→			}
    55→			if def != nil {
    56→				definitions = append(definitions, def)
    57→			}
    58→		} else if p.check(lexer.TknStruct) {
    59→			def, err := p.parseStructDef()
    60→			if err != nil {
    61→				p.errors = append(p.errors, err.Error())
    62→				p.synchronize() // Error recovery
    63→				continue
    64→			}
    65→			if def != nil {
    66→				definitions = append(definitions, def)
    67→			}
    68→		} else {
    69→			stmt, err := p.parseStatement()
    70→			if err != nil {
    71→				p.errors = append(p.errors, err.Error())
    72→				p.synchronize() // Error recovery
    73→				continue
    74→			}
    75→			if stmt != nil {
    76→				mainBody = append(mainBody, stmt)
    77→			}
    78→		}
    79→	}
    80→
    81→	// Return program even if there are errors (for partial parsing)
    82→	if len(p.errors) > 0 {
    83→		return &ast.Program{
    84→			Definitions: definitions,
    85→			MainBody:    mainBody,
    86→		}, fmt.Errorf("parse errors: %v", p.errors)
    87→	}
    88→
    89→	return &ast.Program{
    90→		Definitions: definitions,
    91→		MainBody:    mainBody,
    92→	}, nil
    93→}
    94→
    95→// parseFunctionDef parses a function definition
    96→func (p *Parser) parseFunctionDef() (*ast.FunctionDef, error) {
    97→	if !p.match(lexer.TknFn) {
    98→		return nil, nil
    99→	}
   100→
   101→	name := p.current().Text
   102→	if !p.match(lexer.TknIdentifier) {
   103→		return nil, fmt.Errorf("expected function name at %d:%d", p.current().Line, p.current().Column)
   104→	}
   105→
   106→	if !p.match(lexer.TknLParen) {
   107→		return nil, fmt.Errorf("expected '(' at %d:%d", p.current().Line, p.current().Column)
   108→	}
   109→
   110→	// Parse parameters
   111→	var params []ast.Parameter
   112→	if !p.check(lexer.TknRParen) {
   113→		for {
   114→			paramName := p.current().Text
   115→			if !p.match(lexer.TknIdentifier) {
   116→				return nil, fmt.Errorf("expected parameter name at %d:%d", p.current().Line, p.current().Column)
   117→			}
   118→
   119→			var paramType *ast.Type
   120→			if p.match(lexer.TknColon) {
   121→				// Type annotation
   122→				paramType = p.parseType()
   123→			}
   124→
   125→			params = append(params, ast.Parameter{
   126→				Name: paramName,
   127→				Type: paramType,
   128→			})
   129→
   130→			if !p.match(lexer.TknComma) {
   131→				break
   132→			}
   133→		}
   134→	}
   135→
   136→	if !p.match(lexer.TknRParen) {
   137→		return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   138→	}
   139→
   140→	// Parse return type (V syntax: type directly after params, no ->)
   141→	var returnType *ast.Type
   142→	if !p.check(lexer.TknLBrace) && !p.isAtEnd() {
   143→		// Look ahead to see if next is a type (identifier or keyword type)
   144→		if p.check(lexer.TknIdentifier) || p.isPrimitiveType() {
   145→			returnType = p.parseType()
   146→		}
   147→	}
   148→
   149→	// Parse body
   150→	if !p.match(lexer.TknLBrace) {
   151→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   152→	}
   153→
   154→	var body []ast.Statement
   155→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   156→		stmt, err := p.parseStatement()
   157→		if err != nil {
   158→			return nil, err
   159→		}
   160→		if stmt != nil {
   161→			body = append(body, stmt)
   162→		}
   163→	}
   164→
   165→	if !p.match(lexer.TknRBrace) {
   166→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   167→	}
   168→
   169→	return &ast.FunctionDef{
   170→		Name:       name,
   171→		Parameters: params,
   172→		ReturnType: returnType,
   173→		Body:       body,
   174→	}, nil
   175→}
   176→
   177→// parseTypeDef parses a type definition
   178→// V syntax: type UserId = i64
   179→func (p *Parser) parseTypeDef() (*ast.TypeDef, error) {
   180→	if !p.match(lexer.TknType) {
   181→		return nil, nil
   182→	}
   183→
   184→	name := p.current().Text
   185→	if !p.match(lexer.TknIdentifier) {
   186→		return nil, fmt.Errorf("expected type name at %d:%d", p.current().Line, p.current().Column)
   187→	}
   188→
   189→	if !p.match(lexer.TknAssign) {
   190→		return nil, fmt.Errorf("expected '=' at %d:%d", p.current().Line, p.current().Column)
   191→	}
   192→
   193→	// Parse the underlying type (simple type alias)
   194→	underlyingType := p.parseType()
   195→
   196→	return &ast.TypeDef{
   197→		Name: name,
   198→		Fields: []ast.Field{
   199→			{
   200→				Name: "value",
   201→				Type: underlyingType,
   202→			},
   203→		},
   204→	}, nil
   205→}
   206→
   207→// parseStructDef parses a struct definition
   208→// V syntax: struct Point { x i64, y i64 }
   209→// Field syntax: name type (no colon)
   210→func (p *Parser) parseStructDef() (*ast.StructDef, error) {
   211→	if !p.match(lexer.TknStruct) {
   212→		return nil, nil
   213→	}
   214→
   215→	name := p.current().Text
   216→	if !p.match(lexer.TknIdentifier) {
   217→		return nil, fmt.Errorf("expected struct name at %d:%d", p.current().Line, p.current().Column)
   218→	}
   219→
   220→	if !p.match(lexer.TknLBrace) {
   221→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   222→	}
   223→
   224→	var fields []ast.Field
   225→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   226→		isMutable := p.match(lexer.TknMut)
   227→
   228→		fieldName := p.current().Text
   229→		if !p.match(lexer.TknIdentifier) {
   230→			return nil, fmt.Errorf("expected field name at %d:%d", p.current().Line, p.current().Column)
   231→		}
   232→
   233→		// V syntax: field type (space-separated, no colon)
   234→		fieldType := p.parseType()
   235→
   236→		fields = append(fields, ast.Field{
   237→			Name:    fieldName,
   238→			Type:    fieldType,
   239→			Mutable: isMutable,
   240→		})
   241→
   242→		if !p.match(lexer.TknComma) {
   243→			break
   244→		}
   245→	}
   246→
   247→	if !p.match(lexer.TknRBrace) {
   248→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   249→	}
   250→
   251→	return &ast.StructDef{
   252→		Name:   name,
   253→		Fields: fields,
   254→	}, nil
   255→}
   256→
   257→// parseStatement parses a statement
   258→func (p *Parser) parseStatement() (ast.Statement, error) {
   259→	if p.match(lexer.TknLet) {
   260→		return p.parseLetStatement()
   261→	}
   262→	if p.match(lexer.TknConst) {
   263→		return p.parseConstStatement()
   264→	}
   265→	if p.match(lexer.TknIf) {
   266→		return p.parseIfStatement()
   267→	}
   268→	if p.match(lexer.TknFor) {
   269→		return p.parseForStatement()
   270→	}
   271→	if p.match(lexer.TknMatch) {
   272→		return p.parseMatchStatement()
   273→	}
   274→	if p.match(lexer.TknReturn) {
   275→		return p.parseReturnStatement()
   276→	}
   277→	if p.match(lexer.TknLBrace) {
   278→		return p.parseBlockStatement()
   279→	}
   280→
   281→	// Expression statement
   282→	expr, err := p.parseExpression()
   283→	if err != nil {
   284→		return nil, err
   285→	}
   286→
   287→	// Consume optional semicolon
   288→	p.match(lexer.TknSemicolon)
   289→
   290→	return &ast.ExpressionStatement{Expression: expr}, nil
   291→}
   292→
   293→// parseLetStatement parses a let binding
   294→func (p *Parser) parseLetStatement() (ast.Statement, error) {
   295→	isMutable := p.match(lexer.TknMut)
   296→
   297→	name := p.current().Text
   298→	if !p.match(lexer.TknIdentifier) {
   299→		return nil, fmt.Errorf("expected variable name at %d:%d", p.current().Line, p.current().Column)
   300→	}
   301→
   302→	var varType *ast.Type
   303→	if p.match(lexer.TknColon) {
   304→		varType = p.parseType()
   305→	}
   306→
   307→	var init ast.Expression
   308→	if p.match(lexer.TknAssign) || p.match(lexer.TknColonAssign) {
   309→		var err error
   310→		init, err = p.parseExpression()
   311→		if err != nil {
   312→			return nil, err
   313→		}
   314→	}
   315→
   316→	p.match(lexer.TknSemicolon)
   317→
   318→	return &ast.LetStatement{
   319→		Name:    name,
   320→		Type:    varType,
   321→		Init:    init,
   322→		Mutable: isMutable,
   323→	}, nil
   324→}
   325→
   326→// parseConstStatement parses a const binding
   327→func (p *Parser) parseConstStatement() (ast.Statement, error) {
   328→	name := p.current().Text
   329→	if !p.match(lexer.TknIdentifier) {
   330→		return nil, fmt.Errorf("expected constant name at %d:%d", p.current().Line, p.current().Column)
   331→	}
   332→
   333→	var varType *ast.Type
   334→	if p.match(lexer.TknColon) {
   335→		varType = p.parseType()
   336→	}
   337→
   338→	if !p.match(lexer.TknAssign) {
   339→		return nil, fmt.Errorf("expected '=' at %d:%d", p.current().Line, p.current().Column)
   340→	}
   341→
   342→	value, err := p.parseExpression()
   343→	if err != nil {
   344→		return nil, err
   345→	}
   346→
   347→	p.match(lexer.TknSemicolon)
   348→
   349→	return &ast.ConstStatement{
   350→		Name:  name,
   351→		Type:  varType,
   352→		Value: value,
   353→	}, nil
   354→}
   355→
   356→// parseIfStatement parses an if statement
   357→func (p *Parser) parseIfStatement() (ast.Statement, error) {
   358→	cond, err := p.parseExpression()
   359→	if err != nil {
   360→		return nil, err
   361→	}
   362→
   363→	if !p.match(lexer.TknLBrace) {
   364→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   365→	}
   366→
   367→	var thenBody []ast.Statement
   368→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   369→		stmt, err := p.parseStatement()
   370→		if err != nil {
   371→			return nil, err
   372→		}
   373→		if stmt != nil {
   374→			thenBody = append(thenBody, stmt)
   375→		}
   376→	}
   377→
   378→	if !p.match(lexer.TknRBrace) {
   379→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   380→	}
   381→
   382→	var elseBody []ast.Statement
   383→	if p.match(lexer.TknElse) {
   384→		if p.match(lexer.TknLBrace) {
   385→			for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   386→				stmt, err := p.parseStatement()
   387→				if err != nil {
   388→					return nil, err
   389→				}
   390→				if stmt != nil {
   391→					elseBody = append(elseBody, stmt)
   392→				}
   393→			}
   394→
   395→			if !p.match(lexer.TknRBrace) {
   396→				return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   397→			}
   398→		}
   399→	}
   400→
   401→	return &ast.IfStatement{
   402→		Condition: cond,
   403→		ThenBody:  thenBody,
   404→		ElseBody:  elseBody,
   405→	}, nil
   406→}
   407→
   408→// parseForStatement parses a for loop
   409→func (p *Parser) parseForStatement() (ast.Statement, error) {
   410→	varName := p.current().Text
   411→	if !p.match(lexer.TknIdentifier) {
   412→		return nil, fmt.Errorf("expected variable name at %d:%d", p.current().Line, p.current().Column)
   413→	}
   414→
   415→	if !p.match(lexer.TknIn) {
   416→		return nil, fmt.Errorf("expected 'in' at %d:%d", p.current().Line, p.current().Column)
   417→	}
   418→
   419→	iter, err := p.parseExpression()
   420→	if err != nil {
   421→		return nil, err
   422→	}
   423→
   424→	if !p.match(lexer.TknLBrace) {
   425→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   426→	}
   427→
   428→	var body []ast.Statement
   429→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   430→		stmt, err := p.parseStatement()
   431→		if err != nil {
   432→			return nil, err
   433→		}
   434→		if stmt != nil {
   435→			body = append(body, stmt)
   436→		}
   437→	}
   438→
   439→	if !p.match(lexer.TknRBrace) {
   440→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   441→	}
   442→
   443→	// Check if iter is a range (BinaryExpression with .. operator)
   444→	if binExpr, ok := iter.(*ast.BinaryExpression); ok && binExpr.Operator == ".." {
   445→		return &ast.ForRangeStatement{
   446→			Variable: varName,
   447→			Start:    binExpr.Left,
   448→			End:      binExpr.Right,
   449→			Body:     body,
   450→		}, nil
   451→	}
   452→
   453→	return &ast.ForStatement{
   454→		Variable: varName,
   455→		Iterator: iter,
   456→		Body:     body,
   457→	}, nil
   458→}
   459→
   460→// parseMatchStatement parses a match statement
   461→func (p *Parser) parseMatchStatement() (ast.Statement, error) {
   462→	expr, err := p.parseExpression()
   463→	if err != nil {
   464→		return nil, err
   465→	}
   466→
   467→	if !p.match(lexer.TknLBrace) {
   468→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   469→	}
   470→
   471→	var arms []ast.MatchArm
   472→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   473→		// Parse pattern
   474→		pattern, err := p.parsePattern()
   475→		if err != nil {
   476→			return nil, err
   477→		}
   478→
   479→		if !p.match(lexer.TknFatArrow) {
   480→			return nil, fmt.Errorf("expected '=>' at %d:%d", p.current().Line, p.current().Column)
   481→		}
   482→
   483→		// Parse body
   484→		var body []ast.Statement
   485→		if p.match(lexer.TknLBrace) {
   486→			for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   487→				stmt, err := p.parseStatement()
   488→				if err != nil {
   489→					return nil, err
   490→				}
   491→				if stmt != nil {
   492→					body = append(body, stmt)
   493→				}
   494→			}
   495→			if !p.match(lexer.TknRBrace) {
   496→				return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   497→			}
   498→		} else {
   499→			stmt, err := p.parseStatement()
   500→			if err != nil {
   501→				return nil, err
   502→			}
   503→			if stmt != nil {
   504→				body = append(body, stmt)
   505→			}
   506→		}
   507→
   508→		arms = append(arms, ast.MatchArm{
   509→			Pattern: pattern,
   510→			Body:    body,
   511→		})
   512→
   513→		if !p.match(lexer.TknComma) {
   514→			break
   515→		}
   516→	}
   517→
   518→	if !p.match(lexer.TknRBrace) {
   519→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   520→	}
   521→
   522→	return &ast.MatchStatement{
   523→		Expression: expr,
   524→		Arms:       arms,
   525→	}, nil
   526→}
   527→
   528→// parseReturnStatement parses a return statement
   529→func (p *Parser) parseReturnStatement() (ast.Statement, error) {
   530→	var value ast.Expression
   531→	if !p.check(lexer.TknSemicolon) && !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   532→		var err error
   533→		value, err = p.parseExpression()
   534→		if err != nil {
   535→			return nil, err
   536→		}
   537→	}
   538→
   539→	p.match(lexer.TknSemicolon)
   540→
   541→	return &ast.ReturnStatement{Value: value}, nil
   542→}
   543→
   544→// parseBlockStatement parses a block statement
   545→func (p *Parser) parseBlockStatement() (ast.Statement, error) {
   546→	var statements []ast.Statement
   547→
   548→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   549→		stmt, err := p.parseStatement()
   550→		if err != nil {
   551→			return nil, err
   552→		}
   553→		if stmt != nil {
   554→			statements = append(statements, stmt)
   555→		}
   556→	}
   557→
   558→	if !p.match(lexer.TknRBrace) {
   559→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   560→	}
   561→
   562→	return &ast.BlockStatement{Statements: statements}, nil
   563→}
   564→
   565→// parseExpression parses an expression
   566→func (p *Parser) parseExpression() (ast.Expression, error) {
   567→	return p.parseBinaryExpression(0)
   568→}
   569→
   570→// parseBinaryExpression parses binary expressions with precedence
   571→func (p *Parser) parseBinaryExpression(minPrec int) (ast.Expression, error) {
   572→	left, err := p.parseUnary()
   573→	if err != nil {
   574→		return nil, err
   575→	}
   576→
   577→	for {
   578→		if p.isAtEnd() || !p.isOperator(p.current().Type) {
   579→			break
   580→		}
   581→
   582→		op := p.current()
   583→		prec := getPrecedence(op.Type)
   584→		if prec < minPrec {
   585→			break
   586→		}
   587→
   588→		p.advance()
   589→
   590→		right, err := p.parseBinaryExpression(prec + 1)
   591→		if err != nil {
   592→			return nil, err
   593→		}
   594→
   595→		left = &ast.BinaryExpression{
   596→			Left:     left,
   597→			Operator: op.Text,
   598→			Right:    right,
   599→		}
   600→	}
   601→
   602→	return left, nil
   603→}
   604→
   605→// parseUnary parses unary expressions
   606→func (p *Parser) parseUnary() (ast.Expression, error) {
   607→	if p.match(lexer.TknNot) {
   608→		operand, err := p.parseUnary()
   609→		if err != nil {
   610→			return nil, err
   611→		}
   612→		return &ast.UnaryExpression{
   613→			Operator: "!",
   614→			Operand:  operand,
   615→		}, nil
   616→	}
   617→
   618→	if p.match(lexer.TknMinus) {
   619→		operand, err := p.parseUnary()
   620→		if err != nil {
   621→			return nil, err
   622→		}
   623→		return &ast.UnaryExpression{
   624→			Operator: "-",
   625→			Operand:  operand,
   626→		}, nil
   627→	}
   628→
   629→	if p.match(lexer.TknAmpersand) {
   630→		operand, err := p.parseUnary()
   631→		if err != nil {
   632→			return nil, err
   633→		}
   634→		return &ast.UnaryExpression{
   635→			Operator: "&",
   636→			Operand:  operand,
   637→		}, nil
   638→	}
   639→
   640→	return p.parsePostfix()
   641→}
   642→
   643→// parsePostfix parses postfix expressions
   644→func (p *Parser) parsePostfix() (ast.Expression, error) {
   645→	expr, err := p.parsePrimary()
   646→	if err != nil {
   647→		return nil, err
   648→	}
   649→
   650→	for {
   651→		if p.match(lexer.TknLParen) {
   652→			// Function call
   653→			var args []ast.Expression
   654→			if !p.check(lexer.TknRParen) {
   655→				for {
   656→					arg, err := p.parseExpression()
   657→					if err != nil {
   658→						return nil, err
   659→					}
   660→					args = append(args, arg)
   661→
   662→					if !p.match(lexer.TknComma) {
   663→						break
   664→					}
   665→				}
   666→			}
   667→
   668→			if !p.match(lexer.TknRParen) {
   669→				return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   670→			}
   671→
   672→			expr = &ast.CallExpression{
   673→				Function:  expr,
   674→				Arguments: args,
   675→			}
   676→		} else if p.match(lexer.TknDot) {
   677→			// Field access or method call
   678→			fieldName := p.current().Text
   679→			if !p.match(lexer.TknIdentifier) {
   680→				return nil, fmt.Errorf("expected field name at %d:%d", p.current().Line, p.current().Column)
   681→			}
   682→
   683→			if p.match(lexer.TknLParen) {
   684→				// Method call
   685→				var args []ast.Expression
   686→				if !p.check(lexer.TknRParen) {
   687→					for {
   688→						arg, err := p.parseExpression()
   689→						if err != nil {
   690→							return nil, err
   691→						}
   692→						args = append(args, arg)
   693→
   694→						if !p.match(lexer.TknComma) {
   695→							break
   696→						}
   697→					}
   698→				}
   699→
   700→				if !p.match(lexer.TknRParen) {
   701→					return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   702→				}
   703→
   704→				expr = &ast.MethodCallExpression{
   705→					Object:    expr,
   706→					Method:    fieldName,
   707→					Arguments: args,
   708→				}
   709→			} else {
   710→				// Field access
   711→				expr = &ast.FieldExpression{
   712→					Object: expr,
   713→					Field:  fieldName,
   714→				}
   715→			}
   716→		} else if p.match(lexer.TknLBracket) {
   717→			// Index access
   718→			index, err := p.parseExpression()
   719→			if err != nil {
   720→				return nil, err
   721→			}
   722→
   723→			if !p.match(lexer.TknRBracket) {
   724→				return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   725→			}
   726→
   727→			expr = &ast.IndexExpression{
   728→				Object: expr,
   729→				Index:  index,
   730→			}
   731→		} else if p.match(lexer.TknQuestion) {
   732→			// Error propagation
   733→			expr = &ast.ErrorPropagation{Expression: expr}
   734→		} else {
   735→			break
   736→		}
   737→	}
   738→
   739→	return expr, nil
   740→}
   741→
   742→// parsePrimary parses primary expressions
   743→func (p *Parser) parsePrimary() (ast.Expression, error) {
   744→	// Literals
   745→	if p.match(lexer.TknInteger) {
   746→		val, err := strconv.ParseInt(p.previous().Text, 10, 64)
   747→		if err != nil {
   748→			return nil, fmt.Errorf("invalid integer: %s", p.previous().Text)
   749→		}
   750→		return &ast.IntegerLiteral{Value: val}, nil
   751→	}
   752→
   753→	if p.match(lexer.TknFloat) {
   754→		val, err := strconv.ParseFloat(p.previous().Text, 64)
   755→		if err != nil {
   756→			return nil, fmt.Errorf("invalid float: %s", p.previous().Text)
   757→		}
   758→		return &ast.FloatLiteral{Value: val}, nil
   759→	}
   760→
   761→	if p.match(lexer.TknString) {
   762→		return &ast.StringLiteral{Value: p.previous().Text}, nil
   763→	}
   764→
   765→	if p.match(lexer.TknTrue) {
   766→		return &ast.BoolLiteral{Value: true}, nil
   767→	}
   768→
   769→	if p.match(lexer.TknFalse) {
   770→		return &ast.BoolLiteral{Value: false}, nil
   771→	}
   772→
   773→	if p.match(lexer.TknNone) {
   774→		return &ast.NoneLiteral{}, nil
   775→	}
   776→
   777→	if p.match(lexer.TknIdentifier) {
   778→		return &ast.Identifier{Name: p.previous().Text}, nil
   779→	}
   780→
   781→	if p.match(lexer.TknLBracket) {
   782→		// Array literal
   783→		var elements []ast.Expression
   784→		if !p.check(lexer.TknRBracket) {
   785→			for {
   786→				elem, err := p.parseExpression()
   787→				if err != nil {
   788→					return nil, err
   789→				}
   790→				elements = append(elements, elem)
   791→
   792→				if !p.match(lexer.TknComma) {
   793→					break
   794→				}
   795→			}
   796→		}
   797→
   798→		if !p.match(lexer.TknRBracket) {
   799→			return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   800→		}
   801→
   802→		return &ast.ArrayExpression{Elements: elements}, nil
   803→	}
   804→
   805→	if p.match(lexer.TknIf) {
   806→		// Parse if expression
   807→		cond, err := p.parseExpression()
   808→		if err != nil {
   809→			return nil, err
   810→		}
   811→
   812→		if !p.match(lexer.TknLBrace) {
   813→			return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   814→		}
   815→
   816→		thenExpr, err := p.parseExpression()
   817→		if err != nil {
   818→			return nil, err
   819→		}
   820→
   821→		if !p.match(lexer.TknRBrace) {
   822→			return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   823→		}
   824→
   825→		var elseExpr ast.Expression
   826→		if p.match(lexer.TknElse) {
   827→			if p.match(lexer.TknLBrace) {
   828→				var err error
   829→				elseExpr, err = p.parseExpression()
   830→				if err != nil {
   831→					return nil, err
   832→				}
   833→
   834→				if !p.match(lexer.TknRBrace) {
   835→					return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   836→				}
   837→			}
   838→		}
   839→
   840→		return &ast.IfExpression{
   841→			Condition: cond,
   842→			ThenExpr:  thenExpr,
   843→			ElseExpr:  elseExpr,
   844→		}, nil
   845→	}
   846→
   847→	if p.match(lexer.TknLParen) {
   848→		expr, err := p.parseExpression()
   849→		if err != nil {
   850→			return nil, err
   851→		}
   852→
   853→		if !p.match(lexer.TknRParen) {
   854→			return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   855→		}
   856→
   857→		return expr, nil
   858→	}
   859→
   860→	return nil, fmt.Errorf("unexpected token: %v at %d:%d", p.current().Type, p.current().Line, p.current().Column)
   861→}
   862→
   863→// parsePattern parses a pattern
   864→func (p *Parser) parsePattern() (ast.Pattern, error) {
   865→	if p.match(lexer.TknIdentifier) {
   866→		return &ast.IdentifierPattern{Name: p.previous().Text}, nil
   867→	}
   868→
   869→	if p.match(lexer.TknInteger) {
   870→		val, _ := strconv.ParseInt(p.previous().Text, 10, 64)
   871→		return &ast.LiteralPattern{Value: &ast.IntegerLiteral{Value: val}}, nil
   872→	}
   873→
   874→	if p.match(lexer.TknString) {
   875→		return &ast.LiteralPattern{Value: &ast.StringLiteral{Value: p.previous().Text}}, nil
   876→	}
   877→
   878→	if p.match(lexer.TknTilde) {
   879→		return &ast.WildcardPattern{}, nil
   880→	}
   881→
   882→	return nil, fmt.Errorf("unexpected pattern at %d:%d", p.current().Line, p.current().Column)
   883→}
   884→
   885→// parseType parses a type
   886→func (p *Parser) parseType() *ast.Type {
   887→	// Handle option types (?)
   888→	isOption := p.match(lexer.TknQuestion)
   889→
   890→	// Get base type
   891→	var typeName string
   892→	if p.match(lexer.TknIdentifier) {
   893→		typeName = p.previous().Text
   894→	} else {
   895→		typeName = "unknown"
   896→	}
   897→
   898→	// Handle array types (prefix [])
   899→	isArray := false
   900→	if p.check(lexer.TknLBracket) {
   901→		p.advance()
   902→		if p.match(lexer.TknRBracket) {
   903→			isArray = true
   904→		} else {
   905→			p.pos-- // backtrack
   906→		}
   907→	}
   908→
   909→	return &ast.Type{
   910→		Name:       typeName,
   911→		IsOption:   isOption,
   912→		IsArray:    isArray,
   913→		IsPrimitive: isPrimitiveType(typeName),
   914→	}
   915→}
   916→
   917→// Helper methods
   918→
   919→func (p *Parser) current() lexer.Token {
   920→	if p.pos < len(p.tokens) {
   921→		return p.tokens[p.pos]
   922→	}
   923→	return lexer.Token{Type: lexer.TknEof}
   924→}
   925→
   926→func (p *Parser) previous() lexer.Token {
   927→	if p.pos > 0 {
   928→		return p.tokens[p.pos-1]
   929→	}
   930→	return lexer.Token{Type: lexer.TknEof}
   931→}
   932→
   933→func (p *Parser) advance() lexer.Token {
   934→	curr := p.current()
   935→	if !p.isAtEnd() {
   936→		p.pos++
   937→	}
   938→	return curr
   939→}
   940→
   941→func (p *Parser) match(types ...lexer.TokenType) bool {
   942→	for _, t := range types {
   943→		if p.check(t) {
   944→			p.advance()
   945→			return true
   946→		}
   947→	}
   948→	return false
   949→}
   950→
   951→func (p *Parser) check(t lexer.TokenType) bool {
   952→	if p.isAtEnd() {
   953→		return false
   954→	}
   955→	return p.current().Type == t
   956→}
   957→
   958→func (p *Parser) isAtEnd() bool {
   959→	return p.current().Type == lexer.TknEof
   960→}
   961→
   962→func (p *Parser) isOperator(t lexer.TokenType) bool {
   963→	// Check if token is an operator
   964→	switch t {
   965→	case lexer.TknPlus, lexer.TknMinus, lexer.TknStar, lexer.TknSlash, lexer.TknPercent:
   966→		return true
   967→	case lexer.TknAmpersand, lexer.TknPipe, lexer.TknCaret, lexer.TknTilde:
   968→		return true
   969→	case lexer.TknLeftShift, lexer.TknRightShift:
   970→		return true
   971→	case lexer.TknEq, lexer.TknNe, lexer.TknLt, lexer.TknLe, lexer.TknGt, lexer.TknGe:
   972→		return true
   973→	case lexer.TknLogicalAnd, lexer.TknLogicalOr, lexer.TknNot:
   974→		return true
   975→	case lexer.TknDoubleDot:
   976→		return true
   977→	default:
   978→		return false
   979→	}
   980→}
   981→
   982→func getPrecedence(t lexer.TokenType) int {
   983→	switch t {
   984→	case lexer.TknLogicalOr:
   985→		return 1
   986→	case lexer.TknLogicalAnd:
   987→		return 2
   988→	case lexer.TknEq, lexer.TknNe, lexer.TknLt, lexer.TknLe, lexer.TknGt, lexer.TknGe:
   989→		return 3
   990→	case lexer.TknPlus, lexer.TknMinus:
   991→		return 4
   992→	case lexer.TknStar, lexer.TknSlash, lexer.TknPercent:
   993→		return 5
   994→	case lexer.TknCaret:
   995→		return 6
   996→	case lexer.TknDoubleDot:
   997→		return 3 // Same as comparison for range expressions
   998→	default:
   999→		return 0
  1000→	}
  1001→}
  1002→
  1003→func (p *Parser) isPrimitiveType() bool {
  1004→	if p.current().Type == lexer.TknIdentifier {
  1005→		return isPrimitiveType(p.current().Text)
  1006→	}
  1007→	// Also check for V primitive keywords
  1008→	switch p.current().Type {
  1009→	case lexer.TknTrue, lexer.TknFalse:
  1010→		return true
  1011→	}
  1012→	return false
  1013→}
  1014→
  1015→func isPrimitiveType(name string) bool {
  1016→	switch name {
  1017→	case "i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "string", "char", "int", "float":
  1018→		return true
  1019→	}
  1020→	return false
  1021→}
  1022→
  1023→// synchronize skips tokens until we find a recovery point
  1024→// Used for error recovery to continue parsing after an error
  1025→func (p *Parser) synchronize() {
  1026→	p.advance()
  1027→
  1028→	for !p.isAtEnd() {
  1029→		// Stop at definition keywords
  1030→		if p.check(lexer.TknFn) || p.check(lexer.TknType) || p.check(lexer.TknStruct) ||
  1031→			p.check(lexer.TknInterface) || p.check(lexer.TknEnum) {
  1032→			return
  1033→		}
  1034→
  1035→		// Stop at statement keywords
  1036→		if p.check(lexer.TknLet) || p.check(lexer.TknConst) || p.check(lexer.TknIf) ||
  1037→			p.check(lexer.TknFor) || p.check(lexer.TknReturn) || p.check(lexer.TknMatch) {
  1038→			return
  1039→		}
  1040→
  1041→		// Stop at block boundaries
  1042→		if p.check(lexer.TknRBrace) {
  1043→			p.advance()
  1044→			return
  1045→		}
  1046→
  1047→		p.advance()
  1048→	}
  1049→}
