     3→import (
     4→	"fmt"
     5→	"fv2-lang/internal/ast"
     6→)
     7→
     8→// Checker performs type checking on an AST
     9→type Checker struct {
    10→	GlobalScope *Scope
    11→	CurrentScope *Scope
    12→	Errors      []Error
    13→}
    14→
    15→// New creates a new type checker
    16→func New() *Checker {
    17→	globalScope := NewScope(nil)
    18→
    19→	// Add built-in types
    20→	globalScope.Define("i64", &PrimitiveType{Name: "i64"}, "type")
    21→	globalScope.Define("f64", &PrimitiveType{Name: "f64"}, "type")
    22→	globalScope.Define("string", &PrimitiveType{Name: "string"}, "type")
    23→	globalScope.Define("bool", &PrimitiveType{Name: "bool"}, "type")
    24→	globalScope.Define("none", &PrimitiveType{Name: "none"}, "type")
    25→
    26→	return &Checker{
    27→		GlobalScope: globalScope,
    28→		CurrentScope: globalScope,
    29→		Errors:      []Error{},
    30→	}
    31→}
    32→
    33→// Check performs type checking on the program
    34→func (c *Checker) Check(program *ast.Program) ([]Error, error) {
    35→	// Check definitions first (function, type, struct)
    36→	for _, def := range program.Definitions {
    37→		c.checkDefinition(def)
    38→	}
    39→
    40→	// Check main body
    41→	for _, stmt := range program.MainBody {
    42→		c.checkStatement(stmt)
    43→	}
    44→
    45→	if len(c.Errors) > 0 {
    46→		return c.Errors, fmt.Errorf("type checking failed with %d errors", len(c.Errors))
    47→	}
    48→
    49→	return c.Errors, nil
    50→}
    51→
    52→func (c *Checker) checkDefinition(def ast.Definition) {
    53→	switch d := def.(type) {
    54→	case *ast.FunctionDef:
    55→		c.checkFunctionDef(d)
    56→	case *ast.StructDef:
    57→		c.checkStructDef(d)
    58→	case *ast.TypeDef:
    59→		c.checkTypeDef(d)
    60→	case *ast.InterfaceDef:
    61→		c.checkInterfaceDef(d)
    62→	case *ast.EnumDef:
    63→		c.checkEnumDef(d)
    64→	}
    65→}
    66→
    67→func (c *Checker) checkFunctionDef(fn *ast.FunctionDef) {
    68→	// Create function scope
    69→	fnScope := NewScope(c.CurrentScope)
    70→	prevScope := c.CurrentScope
    71→	c.CurrentScope = fnScope
    72→
    73→	// Add parameters to scope
    74→	paramTypes := []Type{}
    75→	for _, param := range fn.Parameters {
    76→		paramType := c.astTypeToCheckerType(param.Type)
    77→		fnScope.Define(param.Name, paramType, "var")
    78→		paramTypes = append(paramTypes, paramType)
    79→	}
    80→
    81→	// Check return type
    82→	var returnType Type
    83→	if fn.ReturnType != nil {
    84→		returnType = c.astTypeToCheckerType(fn.ReturnType)
    85→	} else {
    86→		returnType = &PrimitiveType{Name: "none"}
    87→	}
    88→
    89→	// Check function body
    90→	for _, stmt := range fn.Body {
    91→		c.checkStatement(stmt)
    92→	}
    93→
    94→	// Register function in parent scope
    95→	fnType := &FunctionType{
    96→		ParamTypes: paramTypes,
    97→		ReturnType: returnType,
    98→	}
    99→	prevScope.Define(fn.Name, fnType, "function")
   100→
   101→	c.CurrentScope = prevScope
   102→}
   103→
   104→func (c *Checker) checkStructDef(str *ast.StructDef) {
   105→	fields := make(map[string]Type)
   106→	for _, field := range str.Fields {
   107→		fieldType := c.astTypeToCheckerType(field.Type)
   108→		fields[field.Name] = fieldType
   109→	}
   110→
   111→	structType := &StructType{
   112→		Name:   str.Name,
   113→		Fields: fields,
   114→	}
   115→
   116→	c.CurrentScope.Define(str.Name, structType, "type")
   117→}
   118→
   119→func (c *Checker) checkTypeDef(td *ast.TypeDef) {
   120→	c.CurrentScope.Define(td.Name, &PrimitiveType{Name: td.Name}, "type")
   121→}
   122→
   123→func (c *Checker) checkInterfaceDef(iface *ast.InterfaceDef) {
   124→	c.CurrentScope.Define(iface.Name, &PrimitiveType{Name: "interface " + iface.Name}, "type")
   125→}
   126→
   127→func (c *Checker) checkEnumDef(enum *ast.EnumDef) {
   128→	c.CurrentScope.Define(enum.Name, &PrimitiveType{Name: "enum " + enum.Name}, "type")
   129→}
   130→
   131→func (c *Checker) checkStatement(stmt ast.Statement) {
   132→	switch s := stmt.(type) {
   133→	case *ast.LetStatement:
   134→		c.checkLetStatement(s)
   135→	case *ast.ConstStatement:
   136→		c.checkConstStatement(s)
   137→	case *ast.IfStatement:
   138→		c.checkIfStatement(s)
   139→	case *ast.ForStatement:
   140→		c.checkForStatement(s)
   141→	case *ast.ForRangeStatement:
   142→		c.checkForRangeStatement(s)
   143→	case *ast.ReturnStatement:
   144→		c.checkReturnStatement(s)
   145→	case *ast.MatchStatement:
   146→		c.checkMatchStatement(s)
   147→	case *ast.ExpressionStatement:
   148→		c.checkExpression(s.Expression)
   149→	case *ast.BlockStatement:
   150→		c.checkBlockStatement(s)
   151→	}
   152→}
   153→
   154→func (c *Checker) checkLetStatement(let *ast.LetStatement) {
   155→	initType := c.checkExpression(let.Init)
   156→
   157→	var declaredType Type
   158→	if let.Type != nil {
   159→		declaredType = c.astTypeToCheckerType(let.Type)
   160→
   161→		// Verify init matches declared type
   162→		if !initType.Equal(declaredType) {
   163→			c.addError(0, 0, fmt.Sprintf(
   164→				"let %s: expected type %s, got %s",
   165→				let.Name, declaredType.TypeString(), initType.TypeString(),
   166→			))
   167→		}
   168→	} else {
   169→		declaredType = initType
   170→	}
   171→
   172→	c.CurrentScope.Define(let.Name, declaredType, "var")
   173→}
   174→
   175→func (c *Checker) checkConstStatement(const_ *ast.ConstStatement) {
   176→	initType := c.checkExpression(const_.Value)
   177→
   178→	var declaredType Type
   179→	if const_.Type != nil {
   180→		declaredType = c.astTypeToCheckerType(const_.Type)
   181→
   182→		if !initType.Equal(declaredType) {
   183→			c.addError(0, 0, fmt.Sprintf(
   184→				"const %s: expected type %s, got %s",
   185→				const_.Name, declaredType.TypeString(), initType.TypeString(),
   186→			))
   187→		}
   188→	} else {
   189→		declaredType = initType
   190→	}
   191→
   192→	c.CurrentScope.Define(const_.Name, declaredType, "const")
   193→}
   194→
   195→func (c *Checker) checkIfStatement(ifStmt *ast.IfStatement) {
   196→	condType := c.checkExpression(ifStmt.Condition)
   197→
   198→	// Condition must be bool
   199→	if !condType.Equal(&PrimitiveType{Name: "bool"}) {
   200→		c.addError(0, 0, fmt.Sprintf(
   201→			"if condition: expected bool, got %s",
   202→			condType.TypeString(),
   203→		))
   204→	}
   205→
   206→	// Check then branch
   207→	for _, stmt := range ifStmt.ThenBody {
   208→		c.checkStatement(stmt)
   209→	}
   210→
   211→	// Check else branch (if any)
   212→	for _, stmt := range ifStmt.ElseBody {
   213→		c.checkStatement(stmt)
   214→	}
   215→}
   216→
   217→func (c *Checker) checkForStatement(forStmt *ast.ForStatement) {
   218→	loopScope := NewScope(c.CurrentScope)
   219→	prevScope := c.CurrentScope
   220→	c.CurrentScope = loopScope
   221→
   222→	c.checkExpression(forStmt.Iterator)
   223→
   224→	// Check body
   225→	for _, stmt := range forStmt.Body {
   226→		c.checkStatement(stmt)
   227→	}
   228→
   229→	c.CurrentScope = prevScope
   230→}
   231→
   232→func (c *Checker) checkForRangeStatement(forStmt *ast.ForRangeStatement) {
   233→	// Check start and end are numeric
   234→	startType := c.checkExpression(forStmt.Start)
   235→	endType := c.checkExpression(forStmt.End)
   236→
   237→	isNumeric := func(t Type) bool {
   238→		if p, ok := t.(*PrimitiveType); ok {
   239→			return p.Name == "i64" || p.Name == "f64"
   240→		}
   241→		return false
   242→	}
   243→
   244→	if !isNumeric(startType) {
   245→		c.addError(0, 0, fmt.Sprintf("range start must be numeric, got %s", startType.TypeString()))
   246→	}
   247→	if !isNumeric(endType) {
   248→		c.addError(0, 0, fmt.Sprintf("range end must be numeric, got %s", endType.TypeString()))
   249→	}
   250→
   251→	// Add loop variable to scope
   252→	loopScope := NewScope(c.CurrentScope)
   253→	prevScope := c.CurrentScope
   254→	c.CurrentScope = loopScope
   255→
   256→	loopScope.Define(forStmt.Variable, startType, "var")
   257→
   258→	// Check body
   259→	for _, stmt := range forStmt.Body {
   260→		c.checkStatement(stmt)
   261→	}
   262→
   263→	c.CurrentScope = prevScope
   264→}
   265→
   266→func (c *Checker) checkReturnStatement(ret *ast.ReturnStatement) {
   267→	if ret.Value != nil {
   268→		c.checkExpression(ret.Value)
   269→	}
   270→}
   271→
   272→func (c *Checker) checkMatchStatement(match *ast.MatchStatement) {
   273→	_ = c.checkExpression(match.Expression)
   274→
   275→	for _, arm := range match.Arms {
   276→		for _, stmt := range arm.Body {
   277→			c.checkStatement(stmt)
   278→		}
   279→	}
   280→}
   281→
   282→func (c *Checker) checkBlockStatement(block *ast.BlockStatement) {
   283→	blockScope := NewScope(c.CurrentScope)
   284→	prevScope := c.CurrentScope
   285→	c.CurrentScope = blockScope
   286→
   287→	for _, stmt := range block.Statements {
   288→		c.checkStatement(stmt)
   289→	}
   290→
   291→	c.CurrentScope = prevScope
   292→}
   293→
   294→func (c *Checker) checkExpression(expr ast.Expression) Type {
   295→	switch e := expr.(type) {
   296→	case *ast.IntegerLiteral:
   297→		return &PrimitiveType{Name: "i64"}
   298→	case *ast.FloatLiteral:
   299→		return &PrimitiveType{Name: "f64"}
   300→	case *ast.StringLiteral:
   301→		return &PrimitiveType{Name: "string"}
   302→	case *ast.BoolLiteral:
   303→		return &PrimitiveType{Name: "bool"}
   304→	case *ast.NoneLiteral:
   305→		return &PrimitiveType{Name: "none"}
   306→	case *ast.Identifier:
   307→		return c.checkIdentifier(e)
   308→	case *ast.BinaryExpression:
   309→		return c.checkBinaryExpression(e)
   310→	case *ast.UnaryExpression:
   311→		return c.checkUnaryExpression(e)
   312→	case *ast.CallExpression:
   313→		return c.checkCallExpression(e)
   314→	case *ast.ArrayExpression:
   315→		return c.checkArrayExpression(e)
   316→	case *ast.FieldExpression:
   317→		return c.checkFieldExpression(e)
   318→	case *ast.IndexExpression:
   319→		return c.checkIndexExpression(e)
   320→	case *ast.IfExpression:
   321→		return c.checkIfExpression(e)
   322→	case *ast.MatchExpression:
   323→		return c.checkMatchExpression(e)
   324→	}
   325→	return &PrimitiveType{Name: "none"}
   326→}
   327→
   328→func (c *Checker) checkIdentifier(ident *ast.Identifier) Type {
   329→	sym := c.CurrentScope.Lookup(ident.Name)
   330→	if sym == nil {
   331→		c.addError(0, 0, fmt.Sprintf("undefined variable: %s", ident.Name))
   332→		return &PrimitiveType{Name: "unknown"}
   333→	}
   334→	return sym.Type
   335→}
   336→
   337→func (c *Checker) checkBinaryExpression(bin *ast.BinaryExpression) Type {
   338→	leftType := c.checkExpression(bin.Left)
   339→	rightType := c.checkExpression(bin.Right)
   340→
   341→	// Type-check operator
   342→	return c.inferBinaryOpType(leftType, rightType, bin.Operator)
   343→}
   344→
   345→func (c *Checker) inferBinaryOpType(left, right Type, op string) Type {
   346→	// Arithmetic operators
   347→	if op == "+" || op == "-" || op == "*" || op == "/" || op == "%" {
   348→		if !c.isNumeric(left) || !c.isNumeric(right) {
   349→			c.addError(0, 0, fmt.Sprintf("arithmetic operator %s requires numeric types", op))
   350→			return left
   351→		}
   352→		if !left.Equal(right) {
   353→			c.addError(0, 0, fmt.Sprintf("type mismatch: %s vs %s", left.TypeString(), right.TypeString()))
   354→		}
   355→		return left
   356→	}
   357→
   358→	// Comparison operators
   359→	if op == "==" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=" {
   360→		return &PrimitiveType{Name: "bool"}
   361→	}
   362→
   363→	// Logical operators
   364→	if op == "&&" || op == "||" {
   365→		if !left.Equal(&PrimitiveType{Name: "bool"}) {
   366→			c.addError(0, 0, "logical operator requires bool")
   367→		}
   368→		return &PrimitiveType{Name: "bool"}
   369→	}
   370→
   371→	return left
   372→}
   373→
   374→func (c *Checker) isNumeric(t Type) bool {
   375→	if p, ok := t.(*PrimitiveType); ok {
   376→		return p.Name == "i64" || p.Name == "f64"
   377→	}
   378→	return false
   379→}
   380→
   381→func (c *Checker) checkUnaryExpression(unary *ast.UnaryExpression) Type {
   382→	exprType := c.checkExpression(unary.Operand)
   383→
   384→	if unary.Operator == "-" {
   385→		if !c.isNumeric(exprType) {
   386→			c.addError(0, 0, "unary minus requires numeric type")
   387→		}
   388→		return exprType
   389→	}
   390→
   391→	if unary.Operator == "!" {
   392→		if !exprType.Equal(&PrimitiveType{Name: "bool"}) {
   393→			c.addError(0, 0, "logical not requires bool")
   394→		}
   395→		return &PrimitiveType{Name: "bool"}
   396→	}
   397→
   398→	return exprType
   399→}
   400→
   401→func (c *Checker) checkCallExpression(call *ast.CallExpression) Type {
   402→	fnType := c.checkExpression(call.Function)
   403→
   404→	if ft, ok := fnType.(*FunctionType); ok {
   405→		// Check argument count
   406→		if len(call.Arguments) != len(ft.ParamTypes) {
   407→			c.addError(0, 0, fmt.Sprintf(
   408→				"function expects %d arguments, got %d",
   409→				len(ft.ParamTypes), len(call.Arguments),
   410→			))
   411→		}
   412→
   413→		// Check argument types
   414→		for i, arg := range call.Arguments {
   415→			if i < len(ft.ParamTypes) {
   416→				argType := c.checkExpression(arg)
   417→				expectedType := ft.ParamTypes[i]
   418→				if !argType.Equal(expectedType) {
   419→					c.addError(0, 0, fmt.Sprintf(
   420→						"argument %d: expected %s, got %s",
   421→						i, expectedType.TypeString(), argType.TypeString(),
   422→					))
   423→				}
   424→			}
   425→		}
   426→
   427→		return ft.ReturnType
   428→	}
   429→
   430→	c.addError(0, 0, "cannot call non-function")
   431→	return &PrimitiveType{Name: "none"}
   432→}
   433→
   434→func (c *Checker) checkArrayExpression(arr *ast.ArrayExpression) Type {
   435→	if len(arr.Elements) == 0 {
   436→		// Empty array - type is ambiguous
   437→		return &ArrayType{ElementType: &PrimitiveType{Name: "unknown"}}
   438→	}
   439→
   440→	firstType := c.checkExpression(arr.Elements[0])
   441→
   442→	// Check all elements have same type
   443→	for i := 1; i < len(arr.Elements); i++ {
   444→		elemType := c.checkExpression(arr.Elements[i])
   445→		if !elemType.Equal(firstType) {
   446→			c.addError(0, 0, fmt.Sprintf(
   447→				"array element %d: expected %s, got %s",
   448→				i, firstType.TypeString(), elemType.TypeString(),
   449→			))
   450→		}
   451→	}
   452→
   453→	return &ArrayType{ElementType: firstType}
   454→}
   455→
   456→func (c *Checker) checkFieldExpression(field *ast.FieldExpression) Type {
   457→	exprType := c.checkExpression(field.Object)
   458→
   459→	if st, ok := exprType.(*StructType); ok {
   460→		if fieldType, ok := st.Fields[field.Field]; ok {
   461→			return fieldType
   462→		}
   463→		c.addError(0, 0, fmt.Sprintf("struct %s has no field %s", st.Name, field.Field))
   464→		return &PrimitiveType{Name: "unknown"}
   465→	}
   466→
   467→	c.addError(0, 0, fmt.Sprintf("cannot access field on %s", exprType.TypeString()))
   468→	return &PrimitiveType{Name: "none"}
   469→}
