   471→func (c *Checker) checkIndexExpression(index *ast.IndexExpression) Type {
   472→	exprType := c.checkExpression(index.Object)
   473→	indexType := c.checkExpression(index.Index)
   474→
   475→	// Index must be numeric
   476→	if !c.isNumeric(indexType) {
   477→		c.addError(0, 0, "array index must be numeric")
   478→	}
   479→
   480→	if at, ok := exprType.(*ArrayType); ok {
   481→		return at.ElementType
   482→	}
   483→
   484→	c.addError(0, 0, fmt.Sprintf("cannot index %s", exprType.TypeString()))
   485→	return &PrimitiveType{Name: "none"}
   486→}
   487→
   488→func (c *Checker) checkIfExpression(ifExpr *ast.IfExpression) Type {
   489→	condType := c.checkExpression(ifExpr.Condition)
   490→
   491→	if !condType.Equal(&PrimitiveType{Name: "bool"}) {
   492→		c.addError(0, 0, "if condition must be bool")
   493→	}
   494→
   495→	thenType := c.checkExpression(ifExpr.ThenExpr)
   496→
   497→	if ifExpr.ElseExpr != nil {
   498→		elseType := c.checkExpression(ifExpr.ElseExpr)
   499→		if !thenType.Equal(elseType) {
   500→			c.addError(0, 0, fmt.Sprintf(
   501→				"if/else branch types mismatch: %s vs %s",
   502→				thenType.TypeString(), elseType.TypeString(),
   503→			))
   504→		}
   505→		return thenType
   506→	}
   507→
   508→	return thenType
   509→}
   510→
   511→func (c *Checker) checkMatchExpression(match *ast.MatchExpression) Type {
   512→	_ = c.checkExpression(match.Expression)
   513→
   514→	if len(match.Arms) == 0 {
   515→		return &PrimitiveType{Name: "none"}
   516→	}
   517→
   518→	var firstType Type
   519→	for i, arm := range match.Arms {
   520→		armType := c.checkExpression(arm.Value)
   521→		if i == 0 {
   522→			firstType = armType
   523→		} else if !armType.Equal(firstType) {
   524→			c.addError(0, 0, fmt.Sprintf(
   525→				"match arm %d: expected %s, got %s",
   526→				i, firstType.TypeString(), armType.TypeString(),
   527→			))
   528→		}
   529→	}
   530→
   531→	if firstType == nil {
   532→		return &PrimitiveType{Name: "none"}
   533→	}
   534→	return firstType
   535→}
   536→
   537→func (c *Checker) astTypeToCheckerType(t *ast.Type) Type {
   538→	if t == nil {
   539→		return &PrimitiveType{Name: "none"}
   540→	}
   541→
   542→	if t.IsArray {
   543→		return &ArrayType{ElementType: c.astTypeToCheckerType(t.ElementType)}
   544→	}
   545→
   546→	return &PrimitiveType{Name: t.Name}
   547→}
